t.script:
(function () {
    var sent = false;
    function send() {
        if (sent) { return; }
        sent = true;
        var tag = document.querySelector('meta[name="mtbg-visit"]');
        var body = JSON.stringify({url: location.href, title: document.title, referrer: document.referrer,
                                   page_id: parseInt((tag ? tag.getAttribute("data-page") : "") || "0", 10) || 0});
        try {
            if (navigator.sendBeacon) {
                if (navigator.sendBeacon("/mtbg/visit", new Blob([body], {type: "text/plain"}))) { return; }
            }
        } catch (e) { /* the fallback below */ }
        try {
            fetch("/mtbg/visit", {method: "POST", body: body, keepalive: true, credentials: "same-origin",
                                  headers: {"Content-Type": "text/plain"}});
        } catch (e) { /* nothing more to do */ }
    }
    if (document.readyState === "loading") {
        document.addEventListener("DOMContentLoaded", send, {once: true});
    } else {
        send();
    }
    addEventListener("pagehide", send, {once: true});
})();
